/* ---------------- B1 · 23: Non-defining relative clauses ---------------- */
L({
  n: 223, lvl: 'B1', t: 'Non-defining relative clauses', ts: 'Bukhara, which…, my uncle, who…', uz: ', who / , which / , whose / , where', topic: 'Culture, art and history',
  gi: 'Defining clause ma’lumotsiz ma’noni to‘ldirmaydi — <b>non-defining</b> esa <b>qo‘shimcha qiziqarli ma’lumot</b> beradi va <b>vergul</b> bilan ajratiladi: «Buxoro, <b>qadimiy ipak yo‘li shahri</b>, juda go‘zal».',
  g: [
    { id: 'form', h: 'Vergul + who / which / whose / where', f: ['ot , *who / which* + fe’l , davomi', 'ot , *whose* + ot + fe’l , davomi', 'ot , *where / when* + gap , davomi'],
      x: '<p><b class="rd">Non-defining</b> — gapni o‘chirib tashlasangiz ham asosiy ma’no saqlanadi, chunki ot allaqachon <b>aniq</b>. U <b class="rd">vergul</b> bilan ajratiladi: «My uncle<b>,</b> who lives in Samarkand<b>,</b> is a historian.» (amakim bitta — aniq)</p><p>Ishlatiladigan so‘zlar: <b>who</b> (odam), <b>which</b> (narsa), <b>whose</b>, <b>where</b>, <b>when</b>. Ammo <b class="rd">that ishlatilmaydi</b> va pronounni <b class="rd">tushirib bo‘lmaydi</b>!</p>',
      key: ['Non-defining = *vergul bilan* ajratiladi', '✗ *that* ishlatilmaydi   |   ✗ pronoun tushmaydi'],
      e: [['My uncle*, who* lives in Samarkand*,* is a historian.', 'Samarqandda yashaydigan amakim tarixchi.', 'man'], ['The Registan*, which* is in Samarkand*,* is world-famous.', 'Samarqanddagi Registon dunyoga mashhur.', 'classical-building'], ['Mozart*, whose* music I love*,* died young.', 'Musiqasini sevadigan Motsart yosh vafot etdi.', 'musical-notes'], ['We visited Khiva*, where* we saw old walls*.*', 'Biz Xivada bo‘ldik, u yerda eski devorlarni ko‘rdik.', 'classical-building'], ['She was born in 1990*, when* the country was young*.*', 'U 1990-yilda tug‘ilgan, o‘shanda mamlakat yosh edi.', 'calendar'], ['My grandmother*, who* is 80*,* tells great stories.', '80 yoshli buvim ajoyib hikoyalar aytadi.', 'older-person']],
      tr: [['Samarqandda yashaydigan amakim tarixchi.', 'My uncle, who lives in Samarkand, is a historian.'], ['Registon, Samarqandda joylashgan, dunyoga mashhur.', 'The Registan, which is in Samarkand, is world-famous.'], ['Buvim, 80 yoshda, ajoyib hikoyalar aytadi.', 'My grandmother, who is 80, tells great stories.']] },
    { id: 'vs', h: 'Defining yoki non-defining? Farq', f: ['vergulsiz, ma’noni aniqlaydi :: *defining*', 'vergul bilan, qo‘shimcha :: *non-defining*', 'that :: faqat defining'],
      x: '<p>Savol: ot <b>bitta va aniq</b>mi (ismi, "mening onam", "Registon")? → <b class="rd">non-defining, vergul</b>. Yoki bir nechtasidan <b>qaysi</b> biri ekanini aniqlashimiz kerakmi? → <b class="rd">defining, vergulsiz</b>.</p><p>«My sister <b>who lives in Paris</b> is a doctor.» (bir nechta opam bor, Parijdagisi) ↔ «My sister<b>, who lives in Paris,</b> is a doctor.» (bitta opam bor).</p>',
      key: ['Bitta, aniq ot → *vergul* (non-defining)', 'Bir nechtadan qaysi biri → *vergulsiz* (defining)'],
      e: [['The man *who* lives upstairs is a poet. (qaysi?)', 'Tepada yashaydigan odam shoir.', 'man'], ['Mr Karimov*, who* lives upstairs*,* is a poet.', 'Tepada yashaydigan Karimov shoir.', 'man'], ['The book *that* I bought is old. (qaysi?)', 'Men sotib olgan kitob eski.', 'books'], ['The Quran*, which* is sacred*,* is read daily.', 'Muqaddas Qur’on har kuni o‘qiladi.', 'open-book'], ['People *who* love art visit museums.', 'San’atni sevadigan odamlar muzeyga boradi.', 'framed-picture'], ['Tashkent*, which* is the capital*,* has a metro.', 'Poytaxt Toshkentda metro bor.', 'metro']],
      tr: [['Opam, Parijda yashaydi, shifokor (bitta opa).', 'My sister, who lives in Paris, is a doctor.'], ['Parijda yashaydigan opam shifokor (bir nechta opa).', 'My sister who lives in Paris is a doctor.'], ['Toshkent, poytaxt, metroga ega.', 'Tashkent, which is the capital, has a metro.']] },
    { id: 'sent', h: ', which — butun gapga ishora', f: ['butun gap haqida :: Gap , *which* + fe’l', 'miqdor :: ot + *of which / of whom*', 'ot + *some of whom / most of which*'],
      x: '<p><b class="rd">, which</b> butun oldingi gapni anglatadi: «He passed the exam<b>, which</b> surprised everyone.» (imtihondan o‘tgani hammani hayron qoldirdi)</p><p>Miqdor bilan: <b class="rd">some of whom / most of which / many of which</b>: «There were 50 guests, <b>most of whom</b> were relatives.» «The museum has 300 paintings, <b>many of which</b> are priceless.»</p><p>Bu uslub yozma nutq va hikoyalarda ko‘p uchraydi.</p>',
      key: ['*, which* = butun oldingi gap haqida', '*some of whom / most of which* = ulardan ba’zilari / ko‘pi'],
      e: [['He passed the exam*, which* surprised everyone.', 'U imtihondan o‘tdi, bu hammani hayron qoldirdi.', 'party-popper'], ['There were 50 guests*, most of whom* were relatives.', '50 ta mehmon bor edi, ularning ko‘pi qarindosh edi.', 'busts-in-silhouette'], ['The museum has 300 paintings*, many of which* are priceless.', 'Muzeyda 300 ta rasm bor, ularning ko‘pi bebaho.', 'framed-picture'], ['She didn’t come*, which* was a pity.', 'U kelmadi, bu afsus edi.', 'pensive-face'], ['We have 20 students*, some of whom* speak Russian.', '20 talabamiz bor, ba’zilari rus tilida gapiradi.', 'busts-in-silhouette'], ['It rained all week*, which* ruined our trip.', 'Hafta davomida yomg‘ir yog‘di, bu safarimizni buzdi.', 'cloud-with-rain']],
      tr: [['U imtihondan o‘tdi, bu hammani hayron qoldirdi.', 'He passed the exam, which surprised everyone.'], ['Mehmonlarning ko‘pi qarindosh edi.', 'Most of the guests were relatives.'], ['Hafta davomida yomg‘ir yog‘di, bu safarimizni buzdi.', 'It rained all week, which ruined our trip.']] },
    { id: 'culture', h: 'Madaniyat va tarix haqida gapirish', f: ['X, *which* dates back to …, is …', 'X, *where* …, is famous for …', 'X, *who* lived in …, was known as …'],
      x: '<p>Tarixiy joy va shaxslarni tavsiflash uchun non-defining juda mos: «The Registan, <b>which dates back to</b> the 15th century, is a UNESCO site.» «Amir Temur, <b>who</b> lived in the 14th century, built an empire.»</p><p>Foydali: <b>date back to</b> (… ga borib taqaladi), <b>be famous for</b>, <b>be known as</b>, <b>be built in</b>, <b>be home to</b>.</p><p><b class="rd">Esda tuting:</b> yil / asr oldidan <b>in</b>: <b>in</b> 1991, <b>in</b> the 15th century.</p>',
      key: ['*dates back to* + davr   |   *is famous for* + nima uchun', '*in* 1991 • *in* the 15th century'],
      e: [['The Registan*, which dates back to* the 15th century*,* is a UNESCO site.', 'XV asrga borib taqaladigan Registon YUNESKO obyekti.', 'classical-building'], ['Amir Temur*, who* lived in the 14th century*,* built an empire.', 'XIV asrda yashagan Amir Temur imperiya qurdi.', 'crown'], ['Bukhara*, which is famous for* its bazaars*,* attracts tourists.', 'Bozorlari bilan mashhur Buxoro sayyohlarni jalb qiladi.', 'shopping-bags'], ['Samarkand*, where* Timur is buried*,* is ancient.', 'Temur dafn etilgan Samarqand qadimiy.', 'classical-building'], ['The museum*, which is home to* thousands of artefacts*,* opens at nine.', 'Minglab artefaktlar saqlanadigan muzey to‘qqizda ochiladi.', 'classical-building'], ['The painting*, which was painted in* 1890*,* is priceless.', '1890-yilda chizilgan rasm bebaho.', 'framed-picture']],
      tr: [['XV asrga borib taqaladigan Registon YUNESKO obyekti.', 'The Registan, which dates back to the 15th century, is a UNESCO site.'], ['Buxoro bozorlari bilan mashhur.', 'Bukhara is famous for its bazaars.'], ['Temur dafn etilgan Samarqand qadimiy.', 'Samarkand, where Timur is buried, is ancient.']] }
  ],
  m: [
    ['My uncle that lives in Samarkand is a historian.', 'My uncle*, who* lives in Samarkand*,* is a historian.', 'Non-defining: that yo‘q.'],
    ['The Registan which is old is famous.', 'The Registan*, which* is old*,* is famous.', 'Vergul kerak.'],
    ['Mozart, that I love, died young.', 'Mozart*, whose music* I love*,* died young.', 'whose + ot.'],
    ['He passed the exam, what surprised us.', 'He passed the exam*, which* surprised us.', 'what yo‘q.'],
    ['Tashkent, is the capital, has a metro.', 'Tashkent*, which* is the capital*,* has a metro.', 'Pronoun tushmaydi.']
  ],
  s: {
    i: 'Bugun madaniyat va tarix haqida gapirasiz: mashhur joylar, shaxslar va qiziqarli faktlarni qo‘shimcha ma’lumot bilan tavsiflaysiz.',
    st: [
      ['Joy', 'X, *which* dates back to …, is …', 'The Registan, which dates back to the 15th century, is a UNESCO site.', 'XV asrga borib taqaladigan Registon YUNESKO obyekti.'],
      ['Shaxs', 'X, *who* + fe’l , is / was …', 'Alisher Navoi, who wrote poetry in Chagatai, is a national hero.', 'Chig‘atoy tilida she’r yozgan Alisher Navoiy milliy qahramon.'],
      ['Joy + faktlar', 'X, *where* …, is famous for …', 'Bukhara, where you can walk through old bazaars, is famous for its crafts.', 'Eski bozorlari bor Buxoro hunarmandchiligi bilan mashhur.'],
      ['Butun gap', '… , *which* + fe’l', 'We visited three museums in one day, which was exhausting.', 'Bir kunda uchta muzeyga bordik, bu charchatuvchi edi.']
    ],
    f: [['Joy', 'X, which dates back to ___, is ___.'], ['Shaxs', 'X, who ___, was ___.'], ['Joy + fakt', 'X, where ___, is famous for ___.'], ['Butun gap', '___, which ___.']],
    a: [['Namuna', 'Last year I visited Bukhara, which is famous for its ancient architecture. We saw the Ark, which dates back to the 5th century, and the Poi Kalon, whose minaret is more than 900 years old. Our guide, who had studied history, told us many legends. We spent three days there, which was not enough.']],
    q: ['What is the most famous historical place in your country?', 'Who is a national hero in your country?', 'Which museum have you visited recently?', 'What traditions are important in your culture?']
  },
  pod: { q: 'history museum', hint: 'qahramon qaysi tarixiy joy yoki shaxs haqida gapiradi (which / who)', use: 'Non-defining relative clauses', pre: ['Hikoyada qaysi joy tilga olindi? Bitta «, which …» gap yozing.'] },
  w: {
    task: 'Tarixiy yoki madaniy joyga sayohatingiz haqida yozing (90+ so‘z): non-defining clauses (, who / , which / , where / , whose) ishlating. Vergulni unutmang.', min: 90, sents: 9,
    plan: ['Qaysi joyga bordim', ', which … (tarix)', ', who … (shaxs / gid)', ', where … (joy)', 'Taassurot (, which was …)'],
    model: 'Last summer I visited Samarkand, which is one of the oldest cities in Central Asia. We saw the Registan, which dates back to the 15th century, and the Gur-Emir, where Amir Temur is buried. Our guide, who was a history teacher, told us fascinating stories. In the evening we tried plov in a small café, whose chef was from Bukhara. It was an unforgettable trip, which I’ll always remember.',
    c: [[', who', ',\\s*who\\b', 1], ['which', ',\\s*which\\b', 1], ['where/whose', ',\\s*(where|whose|when)\\b', 1]],
    sp: { t: 'Imlo: madaniyat so‘zlari.', i: [['architecture', 'architechture', 'ar-chi-tec-ture.'], ['exhibition', 'exibition', 'ex-hi-bi-tion.'], ['civilisation', 'civilization', 'UK: -isation.'], ['ancient', 'ancent', 'an-cient.'], ['monument', 'monumnet', 'mon-u-ment.'], ['tradition', 'traditon', 'tra-di-tion.']] },
    cv: { sit: 'Muzeyda gid bilan suhbat.', who: ['Siz', 'Gid'],
      phr: [['Could you tell me more about…?', '… haqida ko‘proq aytib bera olasizmi?'], ['How old is it?', 'U necha yoshda?'], ['Who painted it?', 'Uni kim chizgan?'], ['It dates back to…', 'U … ga borib taqaladi.']],
      dlg: [[0, '*Could you tell me more about* this painting?'], [1, 'Of course. It was painted by Behzod, who was a famous miniature artist.'], [0, '*How old is it?*'], [1, '*It dates back to* the 15th century, which is when Herat was a cultural centre.'], [0, 'Amazing! And *who* donated it to the museum?'], [1, 'A private collector, whose family kept it for 300 years.']],
      task: 'Endi o‘zingiz shunday suhbat yozing (6–8 replika), non-defining clauses bilan.' }
  },
  tq: [
    ['form', 'My uncle___ who lives in Samarkand___ is a historian.', [', ... ,', ', ...', '... ,'], 0, 'Ikkita vergul.'],
    ['form', 'Mozart, ___ music I love, died young.', ['who', 'whose', 'which'], 1, 'whose music.'],
    ['form', 'We visited Khiva, ___ we saw old walls.', ['where', 'which', 'that'], 0, 'where.'],
    ['vs', 'My sister, ___ lives in Paris, is a doctor. (bitta opa)', ['who', 'that', 'what'], 0, 'who (that yo‘q).'],
    ['vs', 'The book ___ I bought is old.', ['that', ', which', ', who'], 0, 'Defining — that.'],
    ['vs', 'Tashkent, ___ is the capital, has a metro.', ['that', 'which', 'what'], 1, 'which.'],
    ['sent', 'He passed the exam, ___ surprised everyone.', ['which', 'what', 'that'], 0, ', which.'],
    ['sent', 'There were 50 guests, most ___ were relatives.', ['of whom', 'of which', 'who'], 0, 'most of whom.'],
    ['sent', 'The museum has 300 paintings, many ___ are priceless.', ['of which', 'of whom', 'whose'], 0, 'many of which.'],
    ['culture', 'The Registan dates ___ to the 15th century.', ['back', 'up', 'out'], 0, 'date back to.'],
    ['culture', 'Bukhara is famous ___ its bazaars.', ['for', 'by', 'with'], 0, 'famous for.'],
    ['culture', 'Amir Temur lived ___ the 14th century.', ['in', 'at', 'on'], 0, 'in the 14th century.']
  ]
});
